insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types) values ('spot-images','spot-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict (id) do nothing;
create policy "public can view spot images" on storage.objects for select to anon,authenticated using (bucket_id='spot-images');
create policy "admins can upload spot images" on storage.objects for insert to authenticated with check (bucket_id='spot-images' and exists(select 1 from public.admins a where a.user_id=(select auth.uid())));
create policy "admins can update spot images" on storage.objects for update to authenticated using (bucket_id='spot-images' and exists(select 1 from public.admins a where a.user_id=(select auth.uid()))) with check (bucket_id='spot-images' and exists(select 1 from public.admins a where a.user_id=(select auth.uid())));
create policy "admins can delete spot images" on storage.objects for delete to authenticated using (bucket_id='spot-images' and exists(select 1 from public.admins a where a.user_id=(select auth.uid())));